function SpecifySceneLoadingPanel:__init()
    self.co = nil
    self.loadingType = Constants.LoadingType.SpecifyScene
    self.slider = nil
    self.args = nil
    self.dialogArgs = nil
    self.value = 0
    self.isFirst = false
end

function SpecifySceneLoadingPanel:__delete()
    self.co = nil
    self.loadingType = nil
    self.slider = nil
    self.args = nil
    self.dialogArgs = nil
    self.isFirst = nil
end

function SpecifySceneLoadingPanel:SetArg(args, dialogs, loadingType, enableResume)
    self.args = args
    self.dialogArgs = dialogs
    self.loadingType = checkInt(loadingType)
    -- self._loader = loader
end

function SpecifySceneLoadingPanel:Awake()
    self.controller.ClearCache = false
    KTool.SetActive(self.Tips.gameObject, false)
    self.LoadingValueText = KTool.GetComponent(self.LoadingValueText.gameObject, typeof(TextMeshProUGUI))
    self.slider = KTool.GetComponent(self.LoadingValueText.transform.parent.parent.gameObject, typeof(Slider))
    KTool.SetActive(self.controller.gameObject, true)
    -----判断如果进战斗关闭背景音乐
    --开启功程加载
    local path = UICommonUtils.GetLoadingPicUrl(false)

    ---@type UnityEngine.UI.RawImage  -- 修改背景墙
    local rawImage = KTool.GetComponent(self.ImgBg.gameObject, typeof(CS.UnityEngine.UI.RawImage))
    if rawImage then
        local textureLoader = TextureLoader.Load(path, nil, CS.Engine.Modules.LoaderMode.Sync, true)
        if textureLoader.IsSuccess then
            textureLoader:Retain(rawImage)
            rawImage.texture = textureLoader.Asset
        end
        textureLoader:Release()
    end
end

function SpecifySceneLoadingPanel:Start()
    if Config.REVIEW then
        self.LoadingTypeText.text = localize("加载中")
    end
    
    self:__Progress(0)

    -- local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    -- if behaviourAction then
    --     --behaviourAction.UpdateAction = Bind(self, self.Update)
    --     behaviourAction.UpdateAction = function(behaviourAction)
    --         self:Update()
    --     end
    -- end

    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    
    if not isNull(self.args) then
        self.co = cs_coroutine.start(function()
            Application.backgroundLoadingPriority = ThreadPriority.High
            UINavigationBarRoot.Instance:SetActive(false)
            UIModule.StoreStackState(self.args)
            UIModule.Clear()
            ---关闭所有的窗口
            xTry(function()
                local coWait = CoWait.Start()
                for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                    local isRemove = checkBool(v.Argument.isRemove)
                    local coClose = UIModule.CloseDialog(v, isRemove)
                    if not isNull(coClose) then
                        coWait:Coroutine(coClose)
                    end
                end
                UIModule.CurrentScreen.dialogs:Clear()
                while not coWait.IsFinish do
                    coroutine.yield()
                end     
            end)
            KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)

            if self.args then
                cs_coroutine.yield_return(UIModule.OpenScreen(self.args, true, self.dialogArgs))
            end
        end)
    end
end

function SpecifySceneLoadingPanel:__Progress(value)
    --  local image = self.image
    --   if image then
    --     value = math.min(value, 100)
    --     image.fillAmount = checkNumber(value) * 0.01
    value = math.min(value, 1)
    if self._nowProgress and self._nowProgress > value then
        return
    end
    self._nowProgress = value
    local progress = math.floor(checkNumber(value * 100))
    local _string = string.format("%0.1f", progress)
    if self.slider then
        self.slider.value = value
    end
    self.LoadingValueText.text = _string .. "%"
end

function SpecifySceneLoadingPanel:Progress(value)
    value = value / 100
    self.targetValue = value
    local nowValue = self._nowProgress or 0

    if nowValue >= value then
